const query = $('Approval Card Open').first().json.query ?? {};
const approveToken = encodeURIComponent(query.approveToken || '');
const rejectToken = encodeURIComponent(query.rejectToken || '');
const actionPath = '/webhook/hragent-dingtalk-leave-card-action?token=';
const actions = approveToken && rejectToken
  ? `<div class="actions"><a class="approve" href="${actionPath}${approveToken}">同意</a><a class="reject" href="${actionPath}${rejectToken}">拒绝</a></div>`
  : '<p class="error">审批卡片参数无效，请返回钉钉重新打开最新卡片。</p>';
const html = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>请假审批</title><style>body{margin:0;background:#f4f6f8;color:#17202a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.page{min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box}.panel{width:min(420px,100%);background:#fff;border:1px solid #dfe4e8;border-radius:8px;padding:28px;box-sizing:border-box;box-shadow:0 8px 24px rgba(24,39,75,.08)}h1{margin:0 0 10px;font-size:22px}p{margin:0;color:#5f6b76;line-height:1.6}.actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:24px}a{display:flex;align-items:center;justify-content:center;min-height:44px;border-radius:6px;text-decoration:none;font-weight:600}.approve{background:#1677ff;color:#fff}.reject{border:1px solid #d5d9de;color:#b42318;background:#fff}.error{margin-top:20px;color:#b42318}</style></head><body><main class="page"><section class="panel"><h1>请假审批</h1><p>请选择本次申请的处理结果。提交后将以 SaaS 中的最新状态为准。</p>${actions}</section></main></body></html>`;
return [{ json: { html } }];

const raw = $input.first().json ?? {};
const result = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const data = result.data && typeof result.data === 'object' ? result.data : {};
const success = result.success === true;
const status = data.statusLabel || data.status || '';
return [{ json: { success, requestId: data.id ?? null, status, message: success ? (data.alreadyProcessed ? `该申请已经处理过，当前状态：${status}` : `处理成功，当前状态：${status}`) : (result.message || '审批卡片处理失败，请在 SaaS 中查看申请状态') } }];
